select name ||'/'|| id
from  (

	select * 
	from site s
	where device is not null and exists (

		select * 
		from (
				select  jsonb_array_elements(overlay->'name')->'name'->'ishub' AS ishub_value ,id
				FROM template_version
		) as hubs 
		where hubs.id =  s.template_version_id and  hubs.ishub_value = 'true' 
	)
)as h
